const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point([179.35, 64.78]); // Approximate center of Onemen Bay

  const date1_start = '2025-08-04'; // 5 days before Aug 9
  const date1_end = '2025-08-14';   // 5 days after Aug 9
  const date2_start = '2025-09-06'; // 5 days before Sep 11
  const date2_end = '2025-09-16';   // 5 days after Sep 11

  const scale = 100; // Resolution for analysis in meters

  // Sentinel-2 Cloud Masking function (QA60 band)
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B8', 'B4']).rename('NDVI'));
  }

  // 2. Data Acquisition & Check
  const collection1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterBounds(geometry)
                        .filterDate(date1_start, date1_end)
                        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60)) // Initial cloud filter
                        .map(maskS2clouds)
                        .map(addNDVI);

  const collection2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                        .filterBounds(geometry)
                        .filterDate(date2_start, date2_end)
                        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60))
                        .map(maskS2clouds)
                        .map(addNDVI);

  const size1 = await collection1.size().getInfo();
  const size2 = await collection2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2025-08 Images: ${size1}`);
    console.log(`2025-09 Images: ${size2}`);
    console.log("C1");
    return;
  }

  // Get a single representative image (median composite)
  const image1 = collection1.median().select('NDVI');
  const image2 = collection2.median().select('NDVI');

  // 3. Processing & Pixel Count Check
  // Check valid pixels after cloud masking and compositing
  const countReducer = ee.Reducer.count();
  const count1 = await image1.reduceRegion({
    reducer: countReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = await image2.reduceRegion({
    reducer: countReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`2025-08 Images: ${size1} (Val Pixels: ${count1})`);
    console.log(`2025-09 Images: ${size2} (Val Pixels: ${count2})`);
    console.log("C2");
    return;
  }

  // 4. Calculation
  const meanReducer = ee.Reducer.mean();

  const ndvi1_val = await image1.reduceRegion({
    reducer: meanReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2_val = await image2.reduceRegion({
    reducer: meanReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (ndvi1_val === null || isNaN(ndvi1_val) || ndvi2_val === null || isNaN(ndvi2_val)) {
    console.log(`2025-08 Images: ${size1} (Val Pixels: ${count1}, NDVI: ${ndvi1_val})`);
    console.log(`2025-09 Images: ${size2} (Val Pixels: ${count2}, NDVI: ${ndvi2_val})`);
    console.log("C3");
    return;
  }

  console.log(`2025-08 Images: ${size1} (Val Pixels: ${count1}, Mean NDVI: ${ndvi1_val.toFixed(3)})`);
  console.log(`2025-09 Images: ${size2} (Val Pixels: ${count2}, Mean NDVI: ${ndvi2_val.toFixed(3)})`);

  if (ndvi1_val > ndvi2_val) {
    console.log("A"); // More green vegetation on August 9
  } else {
    console.log("B"); // Not more green vegetation on August 9
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
